-- Bilgi arşivi (yalnız veri, canlıya 19.10.2026 uygulandı): Yeninar 2009 güzergâh düzeltmesi, «Ege ekotipi = Muğla arısı» notu, «F1 ana için baba seçimi» kaydı (uzman tahmini). Taze kurulumda 18 kayıt.
update public.bilgi_kayitlari set icerik=replace(replace(icerik,'Güzergâh: Çukurova narenciye → Uluışla yayla → Harran.','Güzergâh: 20 Mayıs Niğde yaylası (kır çiçeği) → 10 Ağustos Urfa (pamuk) → 20 Eylül Samandağ (püren).'),'Muğla ana × Kafkas baba 55,3','Muğla ana × Kafkas baba 55,3'),updated_at=now() where icerik like '%Uluışla%' or icerik like '%Ulukışla%' or icerik like '%Harran%';
update public.bilgi_kayitlari set icerik=icerik||E'\nNot: Ege ekotipi = Muğla arısı (ADÜ kaynakları).',updated_at=now() where id in ('irk-mugla','irk-tek') and icerik not like '%Ege ekotipi = Muğla arısı%';
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('melez-f1-baba','melez','F1 ana için baba seçimi','F1 ana arı (Muğla ana × Kafkas baba) doğada ya da tohumlamayla başka bir babayla çiftleşirse işçiler ¼ Muğla, ¼ Kafkas, ½ baba ırkı olur; F1 özelliği (melez gücü) yarıya iner.
Baba ırkına göre beklenen bal (kg/koloni) — tamamı uzman tahmini:
• Muğla/Ege: 30–50 kg
• Karniyol: 25–50 kg, en sakin
• Kafkas: 22–40 kg
• Orta Anadolu: 20–40 kg
Öneri: Her yıl saf Muğla ana × Kafkas baba yapay tohumlama ile F1 ana yenilenmeli (Akyol 1998 ve Yeninar 2009''da en yüksek verim bu melezde: 65,0 ve 55,3 kg). Not: Ege ekotipi = Muğla arısı (ADÜ kaynakları).','uzman tahmini','[{"ad":"Gençer & Karacaoğlu (2003), YYÜ Tarım Bil. Derg. 13(1)","url":"https://dergipark.org.tr/en/download/article-file/204927"},{"ad":"Ital J Anim Sci (2014), Anatolian/Caucasian/Carniolan","url":"https://doi.org/10.4081/ijas.2014.3409"},{"ad":"Erkan et al. (2024), Biosci. J. 40","url":"https://doi.org/10.14393/bj-v40n0a2024-68555"},{"ad":"Cornuet & Fresnaye","url":"https://eurekamag.com/research/005/585/005585272.php"},{"ad":"Arslan et al. (2004)","url":"https://search.trdizin.gov.tr/en/yayin/detay/110792"},{"ad":"Yeninar, Akyol & Şahinler (2009), J. Anim. Vet. Adv.","url":"https://www.makhillpublications.co/public/index.php/view-article/1680-5593/javaa.2009.995.999"}]'::jsonb,40) on conflict (id) do update set icerik=excluded.icerik,kaynaklar=excluded.kaynaklar,durum=excluded.durum,updated_at=now();
